<?php
require_once __DIR__.'/../model/catalogo_acceso.php';require_once __DIR__.'/../model/tipo_movimiento.php';
$usu=(int)($_SESSION['usu_id_ifact']??0);$csrf=(string)($_SESSION['tipo_movimiento_csrf']??'');$ok=catalogoPuedeAcceder('list_tipos_movimiento.php');if(session_status()===PHP_SESSION_ACTIVE)session_write_close();header('Content-Type: application/json; charset=utf-8');
if(!$usu||!$ok){http_response_code($usu?403:401);echo json_encode(['estado'=>'error','mensaje'=>$usu?'No tienes acceso a Tipos de movimientos.':'Inicia sesión nuevamente.']);exit;}
try{$task=(int)($_REQUEST['task']??0);if(in_array($task,[3,4,5],true)&&($_SERVER['REQUEST_METHOD']!=='POST'||!$csrf||!hash_equals($csrf,(string)($_POST['csrf']??'')))){http_response_code(403);throw new InvalidArgumentException('Actualiza la página antes de guardar.');}$m=new tipo_movimiento();switch($task){case 1:$r=['data'=>$m->listar()];break;case 2:$r=['data'=>$m->obtener((int)($_GET['id']??0))];break;case 3:case 4:$r=['id'=>$m->guardar($usu,$_POST),'mensaje'=>'Tipo de movimiento guardado correctamente.'];break;case 5:$m->eliminar((int)($_POST['id']??0),$usu);$r=['mensaje'=>'Tipo de movimiento eliminado.'];break;case 7:$tipo=strtoupper(trim((string)($_GET['tipo']??'')));$r=['data'=>$m->listar(true,in_array($tipo,['INGRESO','EGRESO'],true)?$tipo:null)];break;default:throw new InvalidArgumentException('Opción no válida.');}echo json_encode(['estado'=>'ok']+$r,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);}catch(InvalidArgumentException $e){http_response_code(422);echo json_encode(['estado'=>'error','mensaje'=>$e->getMessage()]);}catch(Throwable $e){error_log('tipo_movimiento: '.$e->getMessage());http_response_code(500);echo json_encode(['estado'=>'error','mensaje'=>'No se pudo completar la operación.']);}
